ps:
Texture2D g_modelBaseColor : register(t6);
Texture2D g_modelMetalRough : register(t7);
SamplerState g_sampler : register(s0);

cbuffer cbEffect : register(b0)
{
    float g_time;
    float g_audioBass;
    float g_audioMid;
    float g_audioTreble;
    float4 g_params[16];
};

cbuffer cbRaymarchCamera : register(b3)
{
    float3 g_camPos;
    float  _camPad;
    row_major float4x4 g_invViewProj; 
    row_major float4x4 g_viewProj;
};


cbuffer cbMaterial : register(b5)
{
    float4 g_baseColorRate;
    float  g_metallicRate;
    float  g_roughnessRate;
	float  g_hasNormalMap;   
    float _matPad;
};


struct PS_IN {
    float4 pos : SV_Position;
    float2 uv : TEXCOORD0;
    float3 normal : NORMAL;
    float3 viewNormal : NORMAL1;
    float3 worldNormal : NORMAL2;
    float3 worldPos : POSITION1;
    float3 worldTangent : TANGENT;
    nointerpolation uint instID : INSTANCEID;
};

struct PS_OUT {
    float4 target0 : SV_Target0;
    float4 target1 : SV_Target1;
    float4 target2 : SV_Target2;
    float4 target3 : SV_Target3;
    float4 target4 : SV_Target4;
};

PS_OUT main(PS_IN In)
{
    float4 node7_out = float4(0.762500f, 0.866406f, 1.000000f, 1.000000f);
    float4 node5_out = (g_modelBaseColor.Sample(g_sampler, In.uv) * g_baseColorRate);
    float4 node6_out = node5_out * node7_out;
    float4 node4_out = float4(0.141953f, 0.309057f, 0.493750f, 1.000000f);
    float node9_out = 1.000000f;
    PS_OUT o;
    o.target0 = float4((node6_out).xyz, (g_modelMetalRough.Sample(g_sampler, In.uv).b * g_metallicRate));
    o.target1 = float4((normalize(In.worldNormal)) * 0.5 + 0.5, (g_modelMetalRough.Sample(g_sampler, In.uv).g * g_roughnessRate));
    o.target2 = float4(In.worldPos, 1.0);
    o.target3 = float4((node4_out).xyz, node9_out);
    o.target4 = float4(0,0,0,0);
    return o;
}

vs:
Texture2D g_input0 : register(t0);
Texture2D g_input1 : register(t1);
Texture2D g_input2 : register(t2);
Texture2D g_input3 : register(t3);
Texture2D g_input4 : register(t4);
SamplerState g_sampler : register(s0);

cbuffer cbEffect : register(b0)
{
    float g_time;
    float g_audioBass;
    float g_audioMid;
    float g_audioTreble;
    float4 g_params[16];
};

cbuffer cbTransform : register(b1)
{
    row_major float4x4 g_mWVP;
    row_major float4x4 g_mWorldView;
    row_major float4x4 g_mWorld;
};

cbuffer cbRaymarchCamera : register(b3)
{
    float3 g_camPos;
    float  _camPad;
    row_major float4x4 g_invViewProj; 
    row_major float4x4 g_viewProj;
};


struct VS_IN {
    float3 pos : POSITION;
    float2 uv : TEXCOORD0;
    float3 normal : NORMAL;
    float3 tangent : TANGENT;
};

struct PS_IN {
    float4 pos : SV_Position;
    float2 uv : TEXCOORD0;
    float3 normal : NORMAL;
    float3 viewNormal : NORMAL1;
    float3 worldNormal : NORMAL2;
    float3 worldPos : POSITION1;
    float3 worldTangent : TANGENT;
    nointerpolation uint instID : INSTANCEID;
};

PS_IN main(VS_IN In)
{
    PS_IN Out;
    float3 vtxOffset = float3(0.0f, 0.0f, 0.0f);
    float3 localPos = In.pos + vtxOffset;
    Out.pos = mul(float4(localPos, 1.0f), g_mWVP);
    Out.uv = In.uv;
    Out.normal = In.normal;
    Out.viewNormal = normalize(mul(In.normal, (float3x3)g_mWorldView));
    Out.worldNormal = normalize(mul(In.normal, (float3x3)g_mWorld));
    Out.worldPos = mul(float4(localPos, 1.0f), g_mWorld).xyz;
    Out.worldTangent = normalize(mul(In.tangent, (float3x3)g_mWorld));
    Out.instID = 0;
    return Out;
}
